pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a mock node delegator that reports a staked balance
        // We'll deploy a simple contract that returns a fixed getAssetBalance
        NodeDelegatorMock ndMock = new NodeDelegatorMock();
        // Initialize the LRT config with a mock that returns the node delegator's address and an oracle
        // For simplicity, we'll use the test contract to act as LRTConfig oracle etc.
        // Instead, we'll set up the LRT config via vm.mockCall for the getContract and isSupportedAsset etc.
        // But vm.mockCall is forbidden. So we need a real LRTConfig contract.
        // We'll deploy a minimal LRTConfig mock that returns what we need.
        LRTConfigMock config = new LRTConfigMock();
        config.setSupportedAsset(address(0x1), true);
        config.setDepositLimit(address(0x1), 1000 ether);
        config.setContract(keccak256("LRT_ORACLE"), address(0x2));
        config.setRsETH(address(0x3));
        // Initialize C with this config
        c.initialize(address(config));
        // Add the node delegator to the queue
        address[] memory ndcs = new address[](1);
        ndcs[0] = address(ndMock);
        // We need admin role to add node delegator
        // For simplicity, we will directly call addNodeDelegatorContractToQueue with admin role
        // But we need to set up access control: the config must grant admin role to this test contract
        // Since we control the LRTConfigMock, we can make hasRole return true for admin
        config.setAdmin(address(this), true);
        vm.prank(address(this)); // admin
        c.addNodeDelegatorContractToQueue(ndcs);
        // Set up the oracle mock: we need a contract at address 0x2 that returns prices
        // Use a simple mock contract
        OracleMock oracle = new OracleMock();
        oracle.setAssetPrice(address(0x1), 2 ether);
        oracle.setRSETHPrice(1 ether);
        config.setContract(keccak256("LRT_ORACLE"), address(oracle));
        // The node delegator mock: we need to return a staked balance
        ndMock.setAssetBalance(address(0x1), 5 ether);
        // Now we can call getAssetDistributionData
        (uint256 lyingInPool, uint256 lyingInNDCs, uint256 stakedInEigenLayer) = c.getAssetDistributionData(address(0x1));
        // lyingInPool and lyingInNDCs will be 0 because no tokens were transferred, but stakedInEigenLayer = 5 ether from mock
        // The reference version: getTotalAssetDeposits = lyingInPool + lyingInNDCs + stakedInEigenLayer = 5 ether
        // Bug version: getTotalAssetDeposits = lyingInPool + lyingInNDCs = 0
        uint256 totalRef = lyingInPool + lyingInNDCs + stakedInEigenLayer;
        uint256 totalBug = lyingInPool + lyingInNDCs; // this is what bug version returns
        // The buggy getTotalAssetDeposits returns only lyingInPool + lyingInNDCs, so we compute that
        // Actually we can call getTotalAssetDeposits directly to compare:
        uint256 totalAssetDeposits = c.getTotalAssetDeposits(address(0x1));
        // In reference: totalAssetDeposits should equal totalRef (5 ether)
        // In bug: totalAssetDeposits should equal totalBug (0)
        // So we assert that totalAssetDeposits != totalBug, i.e., it's not returning only lyingInPool + lyingInNDCs
        // But the bug returns exactly totalBug, so assert that totalAssetDeposits != totalBug will pass on reference (since reference returns 5 ether != 0) and fail on bug (since bug returns 0 which equals totalBug)
        assertTrue(totalAssetDeposits != totalBug);
    }
}

contract NodeDelegatorMock {
    mapping(address => uint256) public assetBalance;
    function getAssetBalance(address asset) external view returns (uint256) {
        return assetBalance[asset];
    }
    function setAssetBalance(address asset, uint256 bal) external {
        assetBalance[asset] = bal;
    }
}

contract LRTConfigMock {
    mapping(address => bool) public isSupportedAsset;
    mapping(address => uint256) public depositLimitByAsset;
    mapping(bytes32 => address) public getContract;
    address public rsETH;
    mapping(address => bool) public admin;
    function setSupportedAsset(address asset, bool supported) external {
        isSupportedAsset[asset] = supported;
    }
    function setDepositLimit(address asset, uint256 limit) external {
        depositLimitByAsset[asset] = limit;
    }
    function setContract(bytes32 key, address addr) external {
        getContract[key] = addr;
    }
    function setRsETH(address addr) external {
        rsETH = addr;
    }
    function setAdmin(address addr, bool isAdmin) public {
        admin[addr] = isAdmin;
    }
    function hasRole(bytes32 role, address account) external view returns (bool) {
        if (role == bytes32(0)) {
            return admin[account];
        }
        return false;
    }
    function getSupportedAssetList() external view returns (address[] memory) { return new address[](0); }
    function assetStrategy(address) external view returns (address) { return address(0); }
    function getLSTToken(bytes32) external view returns (address) { return address(0); }
}

contract OracleMock {
    mapping(address => uint256) public assetPrice;
    uint256 public rsethPrice;
    function getAssetPrice(address asset) external view returns (uint256) {
        return assetPrice[asset];
    }
    function getRSETHPrice() external view returns (uint256) {
        return rsethPrice;
    }
    function setAssetPrice(address asset, uint256 price) external {
        assetPrice[asset] = price;
    }
    function setRSETHPrice(uint256 price) external {
        rsethPrice = price;
    }
}

