contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: deploy mock contracts for lrtConfig, lrtOracle, and a mock NodeDelegator
        address mockLrtConfig = address(0x123);
        address mockLrtOracle = address(0x456);
        address mockNodeDelegator = address(0x789);
        address rsEthToken = address(0xabc);
        address asset = address(0xdef);

        // Deploy mock contracts as simple contracts that return needed values
        // We'll use vm.etch to deploy minimal bytecode that returns expected values
        // For simplicity, we'll use vm.mockCall but that's not allowed, so we need to deploy actual mock contracts
        // Instead, we'll create a minimal test setup by deploying helper contracts
        // But to keep it simple, we'll just directly set up state via vm.store and other tricks
        // However, vm.store is not allowed. So we'll need to deploy the real contracts with proper constructors.
        // Given the complexity, we'll use a simpler approach: we'll just test the public view function
        // by setting up the lrtConfig and nodeDelegator queue via the public functions.

        // Since we can only interact via c's public surface, we need to:
        // 1. Initialize c with a mock lrtConfig
        // 2. Add a node delegator
        // 3. Call getTotalAssetDeposits

        // For this test to work, we need a real lrtConfig contract that returns isSupportedAsset(true)
        // and depositLimitByAsset(1000). We'll deploy a minimal implementation.

        // Deploy a mock LRTConfig
        MockLRTConfig mockConfig = new MockLRTConfig();
        mockConfig.setIsSupportedAsset(asset, true);
        mockConfig.setDepositLimit(asset, 1000);
        mockConfig.setRsETH(rsEthToken);
        mockConfig.setContractAddress(keccak256("LRT_ORACLE"), address(mockLrtOracle));

        // Deploy a mock LRTOracle
        MockLRTOracle mockOracle = new MockLRTOracle();
        mockOracle.setAssetPrice(asset, 2 ether);
        mockOracle.setRSETHPrice(1 ether);

        // Deploy a mock NodeDelegator
        MockNodeDelegator mockND = new MockNodeDelegator();
        mockND.setAssetBalance(asset, 500);

        // Initialize c
        c.initialize(address(mockConfig));

        // Fund the mock ND with asset tokens so balanceOf returns something
        // We'll need to deploy a mock ERC20
        MockERC20 mockAsset = new MockERC20();
        mockAsset.mint(address(mockND), 200); // lying in NDC
        mockAsset.mint(address(c), 100); // lying in deposit pool

        // Add the node delegator to the queue
        address[] memory ndcs = new address[](1);
        ndcs[0] = address(mockND);
        c.addNodeDelegatorContractToQueue(ndcs);

        // Now call getTotalAssetDeposits
        uint256 totalDeposits = c.getTotalAssetDeposits(asset);

        // Reference version: 100 (pool) + 200 (NDCs) + 500 (staked) = 800
        // Buggy version: 100 (pool) + 200 (NDCs) = 300
        // So we assert that totalDeposits >= 800 (reference includes staked)
        assertTrue(totalDeposits >= 800);
    }
}

contract MockLRTConfig {
    mapping(address => bool) public isSupportedAsset;
    mapping(address => uint256) public depositLimitByAsset;
    address public rsETH;
    mapping(bytes32 => address) public getContract;

    function setIsSupportedAsset(address asset, bool supported) external {
        isSupportedAsset[asset] = supported;
    }

    function setDepositLimit(address asset, uint256 limit) external {
        depositLimitByAsset[asset] = limit;
    }

    function setRsETH(address token) external {
        rsETH = token;
    }

    function setContractAddress(bytes32 key, address addr) external {
        getContract[key] = addr;
    }

    function getSupportedAssetList() external view returns (address[] memory) {
        address[] memory list = new address[](1);
        list[0] = address(0);
        return list;
    }

    function assetStrategy(address) external view returns (address) {
        return address(0);
    }
}

contract MockLRTOracle {
    mapping(address => uint256) public assetPrice;
    uint256 public rsethPrice;

    function setAssetPrice(address asset, uint256 price) external {
        assetPrice[asset] = price;
    }

    function setRSETHPrice(uint256 price) external {
        rsethPrice = price;
    }

    function getAssetPrice(address asset) external view returns (uint256) {
        return assetPrice[asset];
    }

    function getRSETHPrice() external view returns (uint256) {
        return rsethPrice;
    }

    function assetPriceOracle(address) external view returns (address) {
        return address(0);
    }
}

contract MockNodeDelegator {
    mapping(address => uint256) public getAssetBalance;

    function setAssetBalance(address asset, uint256 balance) external {
        getAssetBalance[asset] = balance;
    }
}

contract MockERC20 {
    mapping(address => uint256) public balanceOf;

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }

    function transfer(address, uint256) external returns (bool) {
        return true;
    }

    function transferFrom(address, address, uint256) external returns (bool) {
        return true;
    }

    function totalSupply() external view returns (uint256) { return 0; }
    function allowance(address, address) external view returns (uint256) { return 0; }
    function approve(address, uint256) external returns (bool) { return true; }
}

