contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // deploy supporting contracts
        address rseth = address(new ERC20Mock("rsETH", "rsETH"));
        address asset = address(new ERC20Mock("Asset", "AST"));
        address lrtOracle = address(new LRTMock());
        address lrtConfig = address(new ConfigMock(rseth, lrtOracle));

        // fund this account with asset
        deal(asset, address(this), 1000 ether);

        // initialize C
        c.initialize(lrtConfig);

        // add a node delegator (simple EOA for test)
        address ndc = address(uint160(0x1234));
        address[] memory ndcs = new address[](1);
        ndcs[0] = ndc;
        c.addNodeDelegatorContractToQueue(ndcs);

        // deposit asset
        ERC20Mock(asset).approve(address(c), 100 ether);
        c.depositAsset(asset, 100 ether);

        // now compute what getTotalAssetDeposits should be
        uint256 poolBalance = IERC20(asset).balanceOf(address(c));
        uint256 ndcBalance = IERC20(asset).balanceOf(ndc);
        uint256 ndcStaked = INodeDelegatorMock(ndc).getAssetBalance(asset);
        uint256 expectedTotal = poolBalance + ndcBalance + ndcStaked;

        // actual total from contract
        uint256 actualTotal = c.getTotalAssetDeposits(asset);

        // reference: expectedTotal equals actualTotal (sum of three components)
        // bug: actualTotal equals only poolBalance (first component)
        assertEq(actualTotal, expectedTotal);
    }
}

// minimal ERC20 for testing
contract ERC20Mock {
    string public name;
    string public symbol;
    mapping(address => uint256) balances;
    mapping(address => mapping(address => uint256)) allowances;

    constructor(string memory _name, string memory _symbol) {
        name = _name;
        symbol = _symbol;
    }

    function totalSupply() external view returns (uint256) { return 0; }
    function balanceOf(address account) external view returns (uint256) { return balances[account]; }
    function transfer(address to, uint256 amount) external returns (bool) {
        balances[msg.sender] -= amount;
        balances[to] += amount;
        return true;
    }
    function allowance(address, address) external view returns (uint256) { return 0; }
    function approve(address spender, uint256 amount) external returns (bool) {
        allowances[msg.sender][spender] = amount;
        return true;
    }
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        allowances[from][msg.sender] -= amount;
        balances[from] -= amount;
        balances[to] += amount;
        return true;
    }

    function mint(address to, uint256 amount) public {
        balances[to] += amount;
    }
}

