        // Create a simple ERC20 token for testing
        MockERC20 asset = new MockERC20();

        // Deploy mock LRTConfig
        MockLRTConfig config = new MockLRTConfig();

        // Initialize LRTConfig with the deposit limit
        config.setDepositLimit(address(asset), 1000);
        config.setSupportedAsset(address(asset), true);

        // Set the lrtConfig in contract C
        c.updateLRTConfig(address(config));

        // Also need to set up the rsETH token and oracle so _mintRsETH doesn't revert
        MockRSETH rseth = new MockRSETH();
        config.setRsETH(address(rseth));
