        config.setContract(keccak256("LRT_ORACLE"), address(oracle));

        // Give the test contract some asset tokens to deposit
        asset.mint(address(this), 1000);

        // First deposit 1000 to reach the limit
        asset.approve(address(c), 1000);
        c.depositAsset(address(asset), 1000);

        // Now total deposits = 1000, deposit limit = 1000, so current limit = 0
        // Second deposit should revert with MaximumDepositLimitReached
        // Use try/catch to catch the revert
        bool ok;
