        // In the buggy version, it incorrectly allows the deposit
        assertTrue(!ok);
    }
}

contract MockERC20 {
    string public name = "MockAsset";
    string public symbol = "MA";
    uint8 public decimals = 18;
    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function mint(address to, uint256 amount) external {
        totalSupply += amount;
        balanceOf[to] += amount;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        require(balanceOf[msg.sender] >= amount, "insufficient balance");
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        require(balanceOf[from] >= amount, "insufficient balance");
        require(allowance[from][msg.sender] >= amount, "insufficient allowance");
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        allowance[from][msg.sender] -= amount;
        return true;
    }
}

contract MockLRTConfig {
    mapping(address => bool) public isSupportedAsset;
    mapping(address => uint256) public depositLimitByAsset;
    address public rsETHAddr;
    mapping(bytes32 => address) public contracts;

    function setSupportedAsset(address asset, bool supported) external {
        isSupportedAsset[asset] = supported;
    }

    function setDepositLimit(address asset, uint256 limit) external {
        depositLimitByAsset[asset] = limit;
    }

    function setRsETH(address rseth) external {
        rsETHAddr = rseth;
    }

    function rsETH() external view returns (address) {
        return rsETHAddr;
    }

    function setContract(bytes32 id, address contractAddr) external {
        contracts[id] = contractAddr;
    }

    function getContract(bytes32 id) external view returns (address) {
        return contracts[id];
    }

    function assetStrategy(address) external view returns (address) {
        return address(0);
    }

    function getLSTToken(bytes32) external view returns (address) {
        return address(0);
    }

    function getSupportedAssetList() external view returns (address[] memory) {
        return new address[](0);
    }
}

contract MockRSETH {
    mapping(address => uint256) public balanceOf;
    uint256 public totalSupply;

    function mint(address account, uint256 amount) external {
        balanceOf[account] += amount;
        totalSupply += amount;
    }

    function burn(address account, uint256 amount) external {
        balanceOf[account] -= amount;
        totalSupply -= amount;
    }

    function transfer(address, uint256) external pure returns (bool) { return true; }
    function allowance(address, address) external view returns (uint256) { return 0; }
    function approve(address, uint256) external pure returns (bool) { return true; }
    function transferFrom(address, address, uint256) external pure returns (bool) { return true; }
}

contract MockLRTOracle {
    mapping(address => uint256) public assetPrice;
    uint256 public rsethPrice;
    mapping(address => address) public assetPriceOracle;

    function setAssetPrice(address asset, uint256 price) external {
        assetPrice[asset] = price;
    }

    function setRSETHPrice(uint256 price) external {
        rsethPrice = price;
    }

    function getAssetPrice(address asset) external view returns (uint256) {
        return assetPrice[asset];
    }

    function getRSETHPrice() external view returns (uint256) {
        return rsethPrice;
    }
}

